function reachesBothCoasts(heights: number[][]): number[][] {
  const R = heights.length, C = heights[0].length, out: number[][] = [];
  for (let sr = 0; sr < R; sr++) {
    for (let sc = 0; sc < C; sc++) {
      const seen = new Set<number>([sr * C + sc]);
      const stack = [[sr, sc]];
      let nw = false, se = false;
      while (stack.length && !(nw && se)) {
        const [r, c] = stack.pop()!;
        if (r === 0 || c === 0) nw = true;
        if (r === R - 1 || c === C - 1) se = true;
        for (const [nr, nc] of [[r + 1, c], [r - 1, c], [r, c + 1], [r, c - 1]]) {
          if (nr < 0 || nc < 0 || nr >= R || nc >= C || seen.has(nr * C + nc)) continue;
          if (heights[nr][nc] > heights[r][c]) continue; // rain only runs to a cell no higher
          seen.add(nr * C + nc);
          stack.push([nr, nc]);
        }
      }
      if (nw && se) out.push([sr, sc]);
    }
  }
  return out;
}

