function reachesBothCoasts(heights: number[][]): number[][] {
  const R = heights.length, C = heights[0].length;
  const climb = (seeds: number[][]): boolean[][] => {
    const seen = Array.from({ length: R }, () => new Array(C).fill(false));
    const queue: number[][] = [];
    for (const [r, c] of seeds) if (!seen[r][c]) { seen[r][c] = true; queue.push([r, c]); }
    for (let head = 0; head < queue.length; head++) {
      const [r, c] = queue[head];
      for (const [nr, nc] of [[r + 1, c], [r - 1, c], [r, c + 1], [r, c - 1]]) {
        if (nr < 0 || nc < 0 || nr >= R || nc >= C || seen[nr][nc]) continue;
        if (heights[nr][nc] < heights[r][c]) continue; // walking backwards means walking uphill
        seen[nr][nc] = true;
        queue.push([nr, nc]);
      }
    }
    return seen;
  };
  const nwSeeds: number[][] = [], seSeeds: number[][] = [];
  for (let r = 0; r < R; r++) { nwSeeds.push([r, 0]); seSeeds.push([r, C - 1]); }
  for (let c = 0; c < C; c++) { nwSeeds.push([0, c]); seSeeds.push([R - 1, c]); }
  const nw = climb(nwSeeds), se = climb(seSeeds);
  const out: number[][] = [];
  for (let r = 0; r < R; r++)
    for (let c = 0; c < C; c++)
      if (nw[r][c] && se[r][c]) out.push([r, c]);
  return out;
}

